  "p4b1_g4_earth_space_001": {
    "stem": "Why is the sea near the equator warmer than near the poles?",
    "options": [
      "It receives more direct sunlight throughout the year, which warms the water more.",
      "The Moon heats ocean water more strongly near the equator.",
      "All parts of the sea are equally warm regardless of location.",
      "Wind carrying warm air from the Moon is strongest near the equator."
    ],
    "explanation": "Near the equator, the Sun's rays hit the surface of the ocean at a more direct angle, concentrating more energy into a smaller area. Near the poles, sunlight hits at a low angle and spreads out over a larger area, so it delivers less warmth per square meter of ocean.",
    "theoryLines": [
      "The angle at which sunlight strikes a surface affects how much energy that surface receives.",
      "Ocean currents also move warm and cold water around the globe, affecting temperatures worldwide."
    ]
  },
